// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(new Log()));
    }

    function testFuzz_property(uint256 amount) public {
        uint256 am = bound(amount, 1, 1 ether);
        address attacker = address(this);
        vm.deal(attacker, 2 * am + c.MinDeposit() + 1);

        vm.prank(attacker);
        c.Deposit{value: am + c.MinDeposit() + 1}();
        assertEq(c.balances(attacker), am + c.MinDeposit() + 1);

        vm.prank(attacker);
        c.CashOut(am);

        assertTrue(c.balances(attacker) == 0);
    }

    receive() external payable {
        if (c.balances(address(this)) > 0) {
            c.CashOut(c.balances(address(this)));
        }
    }
}
